import math

def check_condition(n):
    # The expression is E(n) = 3 * ((n+2)! + 1) / (2n - 1)

    # Denominator check (although we know it won't be zero for integer n)
    denominator = 2 * n - 1
    if denominator == 0:
        return False # Should not happen for integer n

    try:
        numerator = 3 * (math.factorial(n + 2) + 1)

        # Check if the expression is an integer
        if numerator % denominator == 0:
            return True
        else:
            return False
    except OverflowError:
        # Should not happen for n <= 15, but good practice
        return False

successful_n = []
for n in range(16): # Checking from n=0 up to n=15
    if check_condition(n):
        successful_n.append(n)

print(f"Successful values of n: {successful_n}")

import math

def is_composite(k):
    if k < 4:
        return False
    for i in range(2, int(math.sqrt(k)) + 1):
        if k % i == 0:
            return True
    return False

def check_solution(n):
    if n < 0:
        return False

    numerator = 3 * (math.factorial(n + 2) + 1)
    denominator = 2 * n - 1

    if denominator == 0:
        return False # Should not happen for non-negative n

    if numerator % denominator == 0:
        return True
    return False

# The task specifically asks to search for solutions where 2n-1 is composite, focusing on n >= 16.
# We search up to n=100 to extend the known set.

solutions_found = []
print("Starting search for n >= 16...")

for n in range(16, 101):
    p = 2 * n - 1
    if is_composite(p):
        if check_solution(n):
            solutions_found.append(n)
            print(f"Solution found: n = {n}, where 2n-1 = {p} is composite.")

if solutions_found:
    print(f"\nSolutions found in this range: {solutions_found}")
else:
    print("\nNo solutions found for composite 2n-1 in the range 16 <= n <= 100.")
